from __future__ import absolute_import, division, print_function,\
    unicode_literals
from future import standard_library
from builtins import object
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass
standard_library.install_aliases()


class UE(with_metaclass(ABCMeta, object)):

    def __init__(self):
        self.ue_type = None

    @abstractmethod
    def attach(self, verify_teid=False, call_type=None):
        pass

    @abstractmethod
    def detach(self):
        pass

    @abstractmethod
    def call_start(self, call_type=None, profile=None):
        pass

    @abstractmethod
    def call_stop(self, call_type=None, profile=None):
        pass

    @abstractmethod
    def configure_ue(self, **kwargs):
        pass

    @abstractmethod
    def call_teardown(self, **kwargs):
        pass
